    writeOSSData(uri, data);
    assertThat(inputFile.exists()).as("OSS file should  exist").isTrue();
    inputFile.exists();
    verify(ossMock, times(1)).getSimplifiedObjectMeta(uri.bucket(), uri.key());
    reset(ossMock);
}

