@Test
public void testFailedCommit() {
    Table table = setupTable();
    GlueTableOperations ops = (GlueTableOperations) ((HasTableOperations) table).operations();
    TableMetadata metadataV1 = ops.current();
    TableMetadata metadataV2 = updateTable(table, ops);
    GlueTableOperations spyOps = Mockito.spy(ops);
    failCommitAndThrowException(spyOps, new CommitFailedException("Datacenter on fire"));
    assertThatThrownBy(() -> spyOps.commit(metadataV2, metadataV1)).isInstanceOf(CommitFailedException.class).hasMessageContaining("Datacenter on fire");
    ops.refresh();
    assertThat(ops.current()).as("Current metadata should not have changed").isEqualTo(metadataV2);
    assertThat(metadataFileExists(metadataV2)).isTrue();
    assertThat(metadataFileCount(ops.current())).as("No new metadata files should exist").isEqualTo(2);
}

