    String dataFileLocation = "s3://bucket/path/to/data-file-2.parquet";
    DataFile dataFile = DataFiles.builder(PartitionSpec.unpartitioned()).withPath(dataFileLocation).withFileSizeInBytes(123L).withFormat(FileFormat.PARQUET).withRecordCount(123L).build();
    String manifestLocation = "s3://bucket/path/to/manifest.avro";
    OutputFile outputFile = s3FileIO.newOutputFile(manifestLocation);
    ManifestWriter<DataFile> writer = ManifestFiles.write(PartitionSpec.unpartitioned(), outputFile);
    writer.add(dataFile);
    writer.close();
    ManifestFile manifest = writer.toManifestFile();
    InputFile inputFile = s3FileIO.newInputFile(manifest);
    reset(s3mock);
    assertThat(inputFile.getLength()).isEqualTo(manifest.length());
    verify(s3mock, never()).headObject(any(HeadObjectRequest.class));
}

private void createRandomObjects(String prefix, int count) {
    S3URI s3URI = new S3URI(prefix);
    random.ints(count).parallel().forEach(i -> s3mock.putObject(builder -> builder.bucket(s3URI.bucket()).key(s3URI.key() + i).build(), RequestBody.empty()));
}

