public void dropTableDataDeletesExpectedFiles() throws IOException {
    table.newFastAppend().appendFile(FILE_A).commit();
    table.newAppend().appendFile(FILE_B).commit();
    StatisticsFile statisticsFile = writeStatsFile(table.currentSnapshot().snapshotId(), table.currentSnapshot().sequenceNumber(), tableLocation + "/metadata/" + UUID.randomUUID() + ".stats", table.io());
    table.updateStatistics().setStatistics(statisticsFile.snapshotId(), statisticsFile).commit();
    PartitionStatisticsFile partitionStatisticsFile = writePartitionStatsFile(table.currentSnapshot().snapshotId(), tableLocation + "/metadata/" + UUID.randomUUID() + ".stats", table.io());
    table.updatePartitionStatistics().setPartitionStatistics(partitionStatisticsFile).commit();
    TableMetadata tableMetadata = readMetadataVersion(5);
    Set<Snapshot> snapshotSet = Sets.newHashSet(table.snapshots());
    Set<String> manifestListLocations = manifestListLocations(snapshotSet);
    Set<String> manifestLocations = manifestLocations(snapshotSet, table.io());
    Set<String> dataLocations = dataLocations(snapshotSet, table.io());
    Set<String> metadataLocations = metadataLocations(tableMetadata);
    Set<String> statsLocations = statsLocations(tableMetadata);
    Set<String> partitionStatsLocations = partitionStatsLocations(tableMetadata);
    assertThat(manifestListLocations).as("should have 2 manifest lists").hasSize(2);
    assertThat(metadataLocations).as("should have 5 metadata locations").hasSize(5);
    assertThat(statsLocations).as("should have 1 stats file").containsExactly(statisticsFile.path());
    assertThat(partitionStatsLocations).as("should have 1 partition stats file").containsExactly(partitionStatisticsFile.path());
    FileIO fileIO = createMockFileIO(table.io());
    CatalogUtil.dropTableData(fileIO, tableMetadata);
    ArgumentCaptor<String> argumentCaptor = ArgumentCaptor.forClass(String.class);
    Mockito.verify(fileIO, Mockito.times(manifestListLocations.size() + manifestLocations.size() + dataLocations.size() + metadataLocations.size() + statsLocations.size() + partitionStatsLocations.size())).deleteFile(argumentCaptor.capture());
    List<String> deletedPaths = argumentCaptor.getAllValues();
    assertThat(deletedPaths).as("should contain all created manifest lists").containsAll(manifestListLocations);
    assertThat(deletedPaths).as("should contain all created manifests").containsAll(manifestLocations);
    assertThat(deletedPaths).as("should contain all created data").containsAll(dataLocations);
    assertThat(deletedPaths).as("should contain all created metadata locations").containsAll(metadataLocations);
    assertThat(deletedPaths).as("should contain all created statistics").containsAll(statsLocations);
    assertThat(deletedPaths).as("should contain all created partition stats files").containsAll(partitionStatsLocations);
}

