private void testClientAuth(String catalogToken, Map<String, String> credentials, Map<String, String> expectedHeaders, String oauth2ServerUri, Map<String, String> optionalOAuthParams) {
    Map<String, String> catalogHeaders = ImmutableMap.of("Authorization", "Bearer " + catalogToken);
    RESTCatalogAdapter adapter = Mockito.spy(new RESTCatalogAdapter(backendCatalog));
    SessionCatalog.SessionContext context = new SessionCatalog.SessionContext(UUID.randomUUID().toString(), "user", credentials, ImmutableMap.of());
    RESTCatalog catalog = new RESTCatalog(context, (config) -> adapter);
    ImmutableMap.Builder<String, String> propertyBuilder = ImmutableMap.builder();
    Map<String, String> initializationProperties = propertyBuilder.put(CatalogProperties.URI, "ignored").put("token", catalogToken).put(OAuth2Properties.OAUTH2_SERVER_URI, oauth2ServerUri).putAll(optionalOAuthParams).build();
    catalog.initialize("prod", initializationProperties);
    assertThat(catalog.tableExists(TableIdentifier.of("ns", "table"))).isFalse();
    Mockito.verify(adapter).execute(eq(HTTPMethod.GET), eq("v1/config"), any(), any(), eq(ConfigResponse.class), eq(catalogHeaders), any());
    // token passes a static token. otherwise, validate a client credentials or token exchange
    // request
    if (!credentials.containsKey("token")) {
        Mockito.verify(adapter).execute(eq(HTTPMethod.POST), eq(oauth2ServerUri), any(), any(), eq(OAuthTokenResponse.class), eq(catalogHeaders), any());
    }
    Mockito.verify(adapter).execute(eq(HTTPMethod.GET), eq("v1/namespaces/ns/tables/table"), any(), any(), eq(LoadTableResponse.class), eq(expectedHeaders), any());
    if (!optionalOAuthParams.isEmpty()) {
        Mockito.verify(adapter).execute(eq(HTTPMethod.POST), eq(oauth2ServerUri), any(), Mockito.argThat(body -> ((Map<String, String>) body).keySet().containsAll(optionalOAuthParams.keySet())), eq(OAuthTokenResponse.class), eq(catalogHeaders), any());
    }
}

