public void testTableSnapshotLoading() {
    RESTCatalogAdapter adapter = Mockito.spy(new RESTCatalogAdapter(backendCatalog));
    RESTCatalog catalog = new RESTCatalog(SessionCatalog.SessionContext.createEmpty(), (config) -> adapter);
    catalog.initialize("test", ImmutableMap.of(CatalogProperties.URI, "ignored", CatalogProperties.FILE_IO_IMPL, "org.apache.iceberg.inmemory.InMemoryFileIO", // default loading to refs only
    "snapshot-loading-mode", "refs"));
    if (requiresNamespaceCreate()) {
        catalog.createNamespace(TABLE.namespace());
    }
    // Create a table with multiple snapshots
    Table table = catalog.createTable(TABLE, SCHEMA);
    table.newFastAppend().appendFile(DataFiles.builder(PartitionSpec.unpartitioned()).withPath("/path/to/data-a.parquet").withFileSizeInBytes(10).withRecordCount(2).build()).commit();
    table.newFastAppend().appendFile(DataFiles.builder(PartitionSpec.unpartitioned()).withPath("/path/to/data-b.parquet").withFileSizeInBytes(10).withRecordCount(2).build()).commit();
    ResourcePaths paths = ResourcePaths.forCatalogProperties(Maps.newHashMap());
    // Respond with only referenced snapshots
    Answer<?> refsAnswer = invocation -> {
        LoadTableResponse originalResponse = (LoadTableResponse) invocation.callRealMethod();
        TableMetadata refsMetadata = TableMetadata.buildFrom(originalResponse.tableMetadata()).suppressHistoricalSnapshots().build();
        // don't call snapshots() directly as that would cause to load all snapshots. Instead,
        // make sure the snapshots field holds exactly 1 snapshot
        assertThat(refsMetadata).extracting("snapshots").asInstanceOf(InstanceOfAssertFactories.list(Snapshot.class)).hasSize(1);
        return LoadTableResponse.builder().withTableMetadata(refsMetadata).addAllConfig(originalResponse.config()).build();
    };
    Mockito.doAnswer(refsAnswer).when(adapter).execute(eq(HTTPMethod.GET), eq(paths.table(TABLE)), eq(ImmutableMap.of("snapshots", "refs")), any(), eq(LoadTableResponse.class), any(), any());
    Table refsTables = catalog.loadTable(TABLE);
    assertThat(refsTables.currentSnapshot()).isEqualTo(table.currentSnapshot());
    // verify that the table was loaded with the refs argument
    verify(adapter, times(1)).execute(eq(HTTPMethod.GET), eq(paths.table(TABLE)), eq(ImmutableMap.of("snapshots", "refs")), any(), eq(LoadTableResponse.class), any(), any());
    // verify that all snapshots are loaded when referenced
    assertThat(refsTables.snapshots()).containsExactlyInAnyOrderElementsOf(table.snapshots());
    verify(adapter, times(1)).execute(eq(HTTPMethod.GET), eq(paths.table(TABLE)), eq(ImmutableMap.of("snapshots", "all")), any(), eq(LoadTableResponse.class), any(), any());
}

