@Test
public void testCleanupUncommitedFilesForCleanableFailures() {
    RESTCatalogAdapter adapter = Mockito.spy(new RESTCatalogAdapter(backendCatalog));
    RESTCatalog catalog = catalog(adapter);
    if (requiresNamespaceCreate()) {
        catalog.createNamespace(TABLE.namespace());
    }
    catalog.createTable(TABLE, SCHEMA);
    DataFile file = DataFiles.builder(PartitionSpec.unpartitioned()).withPath("/path/to/data-a.parquet").withFileSizeInBytes(10).withRecordCount(2).build();
    Table table = catalog.loadTable(TABLE);
    ArgumentCaptor<UpdateTableRequest> captor = ArgumentCaptor.forClass(UpdateTableRequest.class);
    Mockito.doThrow(new NotAuthorizedException("not authorized")).when(adapter).post(any(), any(), any(), any(Map.class), any());
    assertThatThrownBy(() -> catalog.loadTable(TABLE).newFastAppend().appendFile(file).commit()).isInstanceOf(NotAuthorizedException.class);
    verify(adapter, atLeastOnce()).post(eq(RESOURCE_PATHS.table(TABLE)), captor.capture(), any(), any(Map.class), any());
    // Extract the UpdateTableRequest to determine the path of the manifest list that should be
    // cleaned up
    UpdateTableRequest request = captor.getValue();
    MetadataUpdate.AddSnapshot addSnapshot = (MetadataUpdate.AddSnapshot) request.updates().get(0);
    assertThatThrownBy(() -> table.io().newInputFile(addSnapshot.snapshot().manifestListLocation())).isInstanceOf(NotFoundException.class);
}

