@Test
public void testPaginationForListViews() {
    RESTCatalogAdapter adapter = Mockito.spy(new RESTCatalogAdapter(backendCatalog));
    RESTCatalog catalog = new RESTCatalog(SessionCatalog.SessionContext.createEmpty(), (config) -> adapter);
    catalog.initialize("test", ImmutableMap.of(RESTSessionCatalog.REST_PAGE_SIZE, "10"));
    int numberOfItems = 30;
    String namespaceName = "newdb";
    String viewName = "newview";
    // create initial namespace
    catalog().createNamespace(Namespace.of(namespaceName));
    // create several views under namespace, based off a table for listing and verify
    for (int i = 0; i < numberOfItems; i++) {
        TableIdentifier viewIndentifier = TableIdentifier.of(namespaceName, viewName + i);
        catalog.buildView(viewIndentifier).withSchema(SCHEMA).withDefaultNamespace(viewIndentifier.namespace()).withQuery("spark", "select * from ns.tbl").create();
    }
    List<TableIdentifier> views = catalog.listViews(Namespace.of(namespaceName));
    assertThat(views).hasSize(numberOfItems);
    Mockito.verify(adapter).execute(eq(HTTPMethod.GET), eq("v1/config"), any(), any(), eq(ConfigResponse.class), any(), any());
    Mockito.verify(adapter, times(numberOfItems)).execute(eq(HTTPMethod.POST), eq(String.format("v1/namespaces/%s/views", namespaceName)), any(), any(), eq(LoadViewResponse.class), any(), any());
    // verify initial request with empty pageToken
    Mockito.verify(adapter).handleRequest(eq(RESTCatalogAdapter.Route.LIST_VIEWS), eq(ImmutableMap.of("pageToken", "", "pageSize", "10", "namespace", namespaceName)), any(), eq(ListTablesResponse.class));
    // verify second request with update pageToken
    Mockito.verify(adapter).handleRequest(eq(RESTCatalogAdapter.Route.LIST_VIEWS), eq(ImmutableMap.of("pageToken", "10", "pageSize", "10", "namespace", namespaceName)), any(), eq(ListTablesResponse.class));
    // verify third request with update pageToken
    Mockito.verify(adapter).handleRequest(eq(RESTCatalogAdapter.Route.LIST_VIEWS), eq(ImmutableMap.of("pageToken", "20", "pageSize", "10", "namespace", namespaceName)), any(), eq(ListTablesResponse.class));
}

