private List<IcebergWriterResult> sinkWriterTest(Map<String, Object> value, IcebergSinkConfig config) {
    IcebergWriterResult writeResult = new IcebergWriterResult(TableIdentifier.parse(TABLE_NAME), ImmutableList.of(mock(DataFile.class)), ImmutableList.of(), Types.StructType.of());
    IcebergWriter writer = mock(IcebergWriter.class);
    when(writer.complete()).thenReturn(ImmutableList.of(writeResult));
    IcebergWriterFactory writerFactory = mock(IcebergWriterFactory.class);
    when(writerFactory.createWriter(any(), any(), anyBoolean())).thenReturn(writer);
    SinkWriter sinkWriter = new SinkWriter(catalog, config);
    // save a record
    Instant now = Instant.now().truncatedTo(ChronoUnit.MILLIS);
    SinkRecord rec = new SinkRecord("topic", 1, null, "key", null, value, 100L, now.toEpochMilli(), TimestampType.LOG_APPEND_TIME);
    sinkWriter.save(ImmutableList.of(rec));
    SinkWriterResult result = sinkWriter.completeWrite();
    Offset offset = result.sourceOffsets().get(new TopicPartition("topic", 1));
    assertThat(offset).isNotNull();
    // should be 1 more than current offset
    assertThat(offset.offset()).isEqualTo(101L);
    assertThat(offset.timestamp()).isEqualTo(now.atOffset(ZoneOffset.UTC));
    return result.writerResults();
}

